11	// 本文件为“读取已有记录时，同一学生的同一要求只能有一份有效免修”这项
12	// 业务规则提供回归保障。冲突无法经正常申请流程产生（第二份会在提交时被
13	// 拒绝），因此全部用例直接构造记录文件，聚焦 Load 读取历史这一路径：
14	//   - 文件本身完整、可解析，学生、课程、要求确实存在，两份免修依据非空，
15	//     只要同一学生同一要求下有两份编号不同的 approved 免修就整份拒绝；
16	//   - 一份 approved 与 rejected/revoked 历史共存是合法记录：核对只认那份
17	//     有效免修、学分只计一次，历史与原有原因逐条保留，失效申请不重新生效；
18	//   - 唯一性按“学生 + 要求”界定：不同学生共享要求编号、免修编号互不影响。
19	
20	// writeRecord 将 d 序列化到临时记录文件，返回路径与写入的原始字节，
21	// 供调用方在拒绝读取后逐字节比对。
22	func writeRecord(t *testing.T, d *fileData) (path string, raw []byte) {
23		t.Helper()
24		buf, err := json.MarshalIndent(d, "", "  ")
25		if err != nil {
26			t.Fatalf("序列化测试记录失败：%v", err)
27		}
28		buf = append(buf, '\n')
29		path = filepath.Join(t.TempDir(), "records.json")
30		if err := os.WriteFile(path, buf, 0o600); err != nil {
31			t.Fatalf("写入测试记录失败：%v", err)
32		}
33		return path, buf
34	}
35	
36	// waiverConflictBase 构造一份结构完整、引用齐全的基础记录：
37	// 学生 s1 的要求 r1 指向 4 学分课程 c1。可选附一条已通过修读 e1。
38	func waiverConflictBase(withPass bool) *fileData {
39		d := &fileData{
40			Version: recordVersion,
41			Courses: []*Course{
42				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
43			},
44			Students:     []*Student{{ID: "s1"}},
45			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
46		}
47		if withPass {
48			d.Enrollments = []*Enrollment{{
49				ID: "e1", StudentID: "s1", ReqID: "r1", Term: "2024春",
50				Result: Passed, ResultSeq: 1,
51			}}
52			d.NextResultSeq = 1
53		}
54		return d
55	}
56	
57	// assertConflictRejected 是冲突用例的共同断言：Load 必须失败、文件标记为
58	// 已存在，错误点名问题文件、所属学生、目标要求与冲突的两个免修编号，
59	// 且原文件字节完整保留。
60	func assertConflictRejected(t *testing.T, path string, raw []byte, student, req, w1, w2 string) {
61		t.Helper()
62		s, existed, err := Load(path)
63		if err == nil {
64			t.Fatalf("同一学生同一要求存在两份有效免修时必须整份拒绝，却得到 store=%v", s)
65		}
66		if !existed {
67			t.Fatalf("冲突记录应标记为文件已存在，existed=%v err=%v", existed, err)
68		}
69		msg := err.Error()
70		for _, want := range []string{path, "内容损坏", student, req, w1, w2, "有效免修"} {
71			if !strings.Contains(msg, want) {
72				t.Fatalf("错误信息应包含 %q（文件/学生/要求/冲突免修编号），得到：%v", want, err)
73			}
74		}
75		got, readErr := os.ReadFile(path)
76		if readErr != nil {
77			t.Fatal(readErr)
78		}
79		if string(got) != string(raw) {
80			t.Fatalf("拒绝读取不得改写原文件\nwant=%q\n got=%q", raw, got)
81		}
82	}
83	
84	// TestLoadRejectsDuplicateApprovedWaiversInHistory 文件完整可解析、引用齐全、
85	// 两份免修都有非空依据，但同一学生同一要求下有两份编号不同的有效免修：
86	// 无论它们在历史中怎样排列、是否夹杂失效申请、是否另有通过修读、是否还有
87	// 另一名学生的合法同号记录，都必须整份拒绝并保留原文件。
88	func TestLoadRejectsDuplicateApprovedWaiversInHistory(t *testing.T) {
89		approved := func(id, basis string) *Waiver {
90			return &Waiver{ID: id, StudentID: "s1", ReqID: "r1", Basis: basis, Status: WaiverApproved}
91		}
92	
93		t.Run("两份有效免修_先w1后w2", func(t *testing.T) {
94			d := waiverConflictBase(false)
95			d.Waivers = []*Waiver{approved("w1", "学科竞赛获奖"), approved("w2", "外校同层次课程")}
96			path, raw := writeRecord(t, d)
97			assertConflictRejected(t, path, raw, "s1", "r1", "w1", "w2")
98			// 先读到的编号应排在冲突说明前面，证明两份都被点名而不是只报后者。
99			if _, _, err := Load(path); err == nil ||
100				!strings.Contains(err.Error(), "有效免修 w1 与 w2") {
101				t.Fatalf("冲突说明应按读取顺序点名 w1 与 w2，得到：%v", err)
102			}
103		})
104	
105		t.Run("两份有效免修_先w2后w1", func(t *testing.T) {
106			d := waiverConflictBase(false)
107			d.Waivers = []*Waiver{approved("w2", "外校同层次课程"), approved("w1", "学科竞赛获奖")}
108			path, raw := writeRecord(t, d)
109			assertConflictRejected(t, path, raw, "s1", "r1", "w1", "w2")
110			if _, _, err := Load(path); err == nil ||
111				!strings.Contains(err.Error(), "有效免修 w2 与 w1") {
112				t.Fatalf("交换排列后冲突说明应点名 w2 与 w1，不能只报固定的一份，得到：%v", err)
113			}
114		})
115	
116		t.Run("失效申请夹在中间不改变冲突", func(t *testing.T) {
117			d := waiverConflictBase(false)
118			d.Waivers = []*Waiver{
119				approved("w1", "学科竞赛获奖"),
120				{ID: "wx", StudentID: "s1", ReqID: "r1", Basis: "旧依据",
121					Status: WaiverRejected, Reason: "该要求已有有效免修 w1"},
122				approved("w2", "外校同层次课程"),
123			}
124			path, raw := writeRecord(t, d)
125			assertConflictRejected(t, path, raw, "s1", "r1", "w1", "w2")
126		})
127	
128		t.Run("另有通过修读不能掩盖免修冲突", func(t *testing.T) {
129			// 即使该要求已通过修读满足，两份有效免修并存仍然是记录损坏：
130			// 不能拿着通过记录继续核对学分。
131			d := waiverConflictBase(true)
132			d.Waivers = []*Waiver{approved("w1", "学科竞赛获奖"), approved("w2", "外校同层次课程")}
133			path, raw := writeRecord(t, d)
134			assertConflictRejected(t, path, raw, "s1", "r1", "w1", "w2")
135		})
136	
137		t.Run("无关学生的合法同号记录不背锅", func(t *testing.T) {
138			// s2 各自只有一份有效免修，完全合法；s1 名下的冲突仍要整份拒绝，
139			// 且错误应归属 s1，不能误报成 s2 的同一要求被重复取代。
140			d := waiverConflictBase(false)
141			d.Courses = append(d.Courses, &Course{ID: "c2", Name: "线性代数", Credit: 3, Open: true})
142			d.Students = append(d.Students, &Student{ID: "s2"})
143			d.Requirements = append(d.Requirements, &Requirement{ID: "r1", StudentID: "s2", CourseID: "c2"})
144			d.Waivers = []*Waiver{
145				approved("w1", "学科竞赛获奖"),
146				approved("w2", "外校同层次课程"),
147				{ID: "w1", StudentID: "s2", ReqID: "r1", Basis: "s2 的依据", Status: WaiverApproved},
148			}
149			path, raw := writeRecord(t, d)
150			s, existed, err := Load(path)
151			if err == nil {
152				t.Fatalf("s1 名下冲突时必须整份拒绝，不能只加载 s2 的合法部分，得到 store=%v", s)
153			}
154			if !existed {
155				t.Fatalf("冲突记录应标记为已存在，existed=%v", existed)
156			}
157			msg := err.Error()
158			if !strings.Contains(msg, "s1") || !strings.Contains(msg, "w1") || !strings.Contains(msg, "w2") {
159				t.Fatalf("冲突应归属 s1 并点名 w1/w2，得到：%v", err)
160			}
161			if strings.Contains(msg, "学生 s2") {
162				t.Fatalf("s2 只有一份有效免修，不应被点名为冲突方，得到：%v", err)
163			}
164			got, readErr := os.ReadFile(path)
165			if readErr != nil {
166				t.Fatal(readErr)
167			}
168			if string(got) != string(raw) {
169				t.Fatal("拒绝读取不得改写原文件")
170			}
171		})
172	}
173	
174	// mixedHistory 构造同一要求 r1 下三种状态各一份的免修历史，
175	// 排列由调用方给定。
176	func mixedHistory(order []string) []*Waiver {
177		byID := map[string]*Waiver{
178			"wa": {ID: "wa", StudentID: "s1", ReqID: "r1",
179				Basis: "外校同层次课程", Status: WaiverApproved},
180			"wr": {ID: "wr", StudentID: "s1", ReqID: "r1",
181				Basis: "再次申请的新依据", Status: WaiverRejected, Reason: "该要求已有有效免修 wa"},
182			"wv": {ID: "wv", StudentID: "s1", ReqID: "r1",
183				Basis: "原竞赛材料", Status: WaiverRevoked, Reason: "材料无法核实"},
184		}
185		var ws []*Waiver
186		for _, id := range order {
187			ws = append(ws, byID[id])
188		}
189		return ws
190	}
191	
192	// assertMixedHistoryLoaded 核对加载后的记录：唯一有效免修 wa 说明来源、
193	// 课程学分只计一次，被拒绝与已撤销历史逐条保留原编号、依据、状态与原因。
194	func assertMHistoryLoaded(t *testing.T, s *Store, order []string, withPass bool) {
195		t.Helper()
196		rep := s.CheckStudent("s1")
197		if rep.TotalCredits != 4 {
198			t.Fatalf("只应以一份有效免修计一次 4 学分，得到 %d", rep.TotalCredits)
199		}
200		if len(rep.Unmet) != 0 {
201			t.Fatalf("r1 应由有效免修满足，未满足=%v", rep.Unmet)
202		}
203		if len(rep.Requirements) != 1 {
204			t.Fatalf("应只有一项要求，得到 %d", len(rep.Requirements))
205		}
206		st := rep.Requirements[0]
207		if !st.Satisfied || st.Source != "waiver" || st.WaiverID != "wa" {
208			t.Fatalf("来源应是唯一有效免修 wa，失效申请不能参与满足，得到 %+v", st)
209		}
210		if withPass {
211			if len(st.PassedEnrollmentIDs) != 1 || st.PassedEnrollmentIDs[0] != "e1" {
212				t.Fatalf("通过修读历史应保留但不重复计学分，得到 %v", st.PassedEnrollmentIDs)
213			}
214		} else if len(st.PassedEnrollmentIDs) != 0 {
215			t.Fatalf("没有修读时通过历史应为空，得到 %v", st.PassedEnrollmentIDs)
216		}
217	
218		// 被拒绝与已撤销申请各按原记录列出，原因保留。
219		if len(rep.RejectedWaivers) != 1 {
220			t.Fatalf("应保留 1 条被拒绝申请，得到 %d", len(rep.RejectedWaivers))
221		}
222		rj := rep.RejectedWaivers[0]
223		if rj.Waiver.ID != "wr" || rj.Waiver.Basis != "再次申请的新依据" ||
224			rj.Waiver.Status != WaiverRejected || rj.Reason != "该要求已有有效免修 wa" {
225			t.Fatalf("被拒绝记录应保留原编号、依据、状态与原因，得到 %+v", rj)
226		}
227		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "wv" {
228			t.Fatalf("应列出 1 条已撤销免修 wv，得到 %v", rep.RevokedWaivers)
229		}
230	
231		// 免修历史完整保留三条且顺序与文件一致，不能为去重丢掉任何一条。
232		ws := s.Waivers("s1")
233		if len(ws) != 3 {
234			t.Fatalf("免修历史应完整保留 3 条，得到 %d", len(ws))
235		}
236		for i, wantID := range order {
237			if ws[i].ID != wantID {
238				t.Fatalf("免修历史顺序应与记录一致，第 %d 条想要 %s 得到 %s（全部=%v）",
239					i, wantID, ws[i].ID, ws)
240			}
241		}
242		if w := s.Waiver("s1", "wv"); w == nil || w.Status != WaiverRevoked ||
243			w.Basis != "原竞赛材料" || w.Reason != "材料无法核实" {
244			t.Fatalf("已撤销免修应保留原依据与撤销原因，得到 %+v", w)
245		}
246		if w := s.Waiver("s1", "wr"); w == nil || w.Status != WaiverRejected ||
247			w.Reason != "该要求已有有效免修 wa" {
248			t.Fatalf("已拒绝免修应保留原拒绝原因，得到 %+v", w)
249		}
250		if w := s.Waiver("s1", "wa"); w == nil || w.Status != WaiverApproved {
251			t.Fatalf("wa 应保持有效，得到 %+v", w)
252		}
253	}
254	
255	// TestLoadMixedWaiverHistoryUsesSingleValidSource 同一要求下一份有效免修与
256	// 已拒绝、已撤销申请共存是合法记录：历史排在有效申请之前或之后结论相同；
257	// 另有通过修读时仍只计一次学分、以免修说明来源；重新保存再加载历史不丢失。
258	func TestLoadMixedWaiverHistoryUsesSingleValidSource(t *testing.T) {
259		orders := map[string][]string{
260			"失效历史在有效之后": {"wa", "wr", "wv"},
261			"失效历史在有效之前": {"wr", "wv", "wa"},
262			"有效申请夹在中间":  {"wr", "wa", "wv"},
263		}
264		for name, order := range orders {
265			t.Run(name, func(t *testing.T) {
266				d := waiverConflictBase(false)
267				d.Waivers = mixedHistory(order)
268				path, _ := writeRecord(t, d)
269				s, existed, err := Load(path)
270				if err != nil || !existed {
271					t.Fatalf("一份有效与失效历史共存应正常打开，existed=%v err=%v", existed, err)
272				}
273				assertMHistoryLoaded(t, s, order, false)
274			})
275		}
276	
277		// 有效免修与通过修读并存：历史排列任意，学分仍只计一次、来源仍是免修。
278		d := waiverConflictBase(true)
279		d.Waivers = mixedHistory([]string{"wr", "wv", "wa"})
280		path, _ := writeRecord(t, d)
281		s, _, err := Load(path)
282		if err != nil {
283			t.Fatalf("含通过修读与混合历史的合法记录应可加载：%v", err)
284		}
285		assertMHistoryLoaded(t, s, []string{"wr", "wv", "wa"}, true)
286	
287		// 重新保存后再次加载：混合历史、来源与学分完全保持，不会在下一次读取时
288		// 被误判为冲突。
289		path2 := filepath.Join(t.TempDir(), "records.json")
290		if err := s.Save(path2); err != nil {
291			t.Fatalf("Save: %v", err)
292		}
293		reloaded, existed, err := Load(path2)
294		if err != nil || !existed {
295			t.Fatalf("混合历史重新保存后应可再次加载，existed=%v err=%v", existed, err)
296		}
297		assertMHistoryLoaded(t, reloaded, []string{"wr", "wv", "wa"}, true)
298	}
299	
300	// TestLoadInvalidWaiversAloneDoNotSatisfyRequirement 只有已拒绝与已撤销申请、
301	// 没有有效免修时记录合法，但要求必须未满足、学分为零：失效申请不能重新参与
302	// 满足要求；历史与原因仍完整可查。
303	func TestLoadInvalidWaiversAloneDoNotSatisfyRequirement(t *testing.T) {
304		d := waiverConflictBase(false)
305		d.Waivers = []*Waiver{
306			// 被拒绝申请允许依据为空（读取只要求有效免修依据非空）。
307			{ID: "wr", StudentID: "s1", ReqID: "r1", Basis: "",
308				Status: WaiverRejected, Reason: "免修依据为空"},
309			{ID: "wv", StudentID: "s1", ReqID: "r1", Basis: "原竞赛材料",
310				Status: WaiverRevoked, Reason: "材料无法核实"},
311		}
312		path, _ := writeRecord(t, d)
313		s, _, err := Load(path)
314		if err != nil {
315			t.Fatalf("仅含失效申请的记录应正常打开：%v", err)
316		}
317		rep := s.CheckStudent("s1")
318		if rep.TotalCredits != 0 {
319			t.Fatalf("失效免修不应产生学分，得到 %d", rep.TotalCredits)
320		}
321		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
322			t.Fatalf("r1 应未满足，得到 %v", rep.Unmet)
323		}
324		st := rep.Requirements[0]
325		if st.Satisfied || st.Source != "" || st.WaiverID != "" {
326			t.Fatalf("失效申请不能成为来源，得到 %+v", st)
327		}
328		if len(rep.RejectedWaivers) != 1 || rep.RejectedWaivers[0].Waiver.ID != "wr" ||
329			rep.RejectedWaivers[0].Reason != "免修依据为空" {
330			t.Fatalf("应保留被拒绝记录与原因，得到 %+v", rep.RejectedWaivers)
331		}
332		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "wv" {
333			t.Fatalf("应保留已撤销记录 wv，得到 %v", rep.RevokedWaivers)
334		}
335		if ws := s.Waivers("s1"); len(ws) != 2 || ws[0].ID != "wr" || ws[1].ID != "wv" {
336			t.Fatalf("两条失效历史都应保留且顺序不变，得到 %+v", ws)
337		}
338	}
339	
340	// TestLoadSameReqAndWaiverIDAcrossStudentsLoadsSeparately 唯一性只按
341	// “同一学生名下的同一要求”界定：两名学生共用要求编号 r1、共用免修编号 w1，
342	// 各自只有一份有效申请时记录合法，核对分别得到本人课程的学分与本人的免修
343	// 来源，不能误报为同一要求被重复取代。同一学生的不同要求也可各有一份免修。
344	func TestLoadSameReqAndWaiverIDAcrossStudentsLoadsSeparately(t *testing.T) {
345		d := &fileData{
346			Version: recordVersion,
347			Courses: []*Course{
348				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
349				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
350			},
351			Students: []*Student{{ID: "s1"}, {ID: "s2"}},
352			Requirements: []*Requirement{
353				{ID: "r1", StudentID: "s1", CourseID: "c1"},
354				{ID: "r2", StudentID: "s1", CourseID: "c2"},
355				{ID: "r1", StudentID: "s2", CourseID: "c2"},
356			},
357			Waivers: []*Waiver{
358				{ID: "w1", StudentID: "s1", ReqID: "r1", Basis: "s1-r1 依据", Status: WaiverApproved},
359				{ID: "w2", StudentID: "s1", ReqID: "r2", Basis: "s1-r2 依据", Status: WaiverApproved},
360				{ID: "w1", StudentID: "s2", ReqID: "r1", Basis: "s2-r1 依据", Status: WaiverApproved},
361			},
362		}
363		path, raw := writeRecord(t, d)
364		s, existed, err := Load(path)
365		if err != nil || !existed {
366			t.Fatalf("跨学生共享编号且各自唯一应正常读取，existed=%v err=%v", existed, err)
367		}
368	
369		// s1：两项要求共 4+3=7 学分，来源分别是本人的 w1、w2，课程各不相同。
370		rep1 := s.CheckStudent("s1")
371		if rep1.TotalCredits != 7 || len(rep1.Unmet) != 0 {
372			t.Fatalf("s1 应得 7 学分且全部满足，得到学分=%d 未满足=%v", rep1.TotalCredits, rep1.Unmet)
373		}
374		if st := rep1.Requirements[0]; st.Req.ID != "r1" || st.Source != "waiver" ||
375			st.WaiverID != "w1" || st.Course.ID != "c1" || st.Course.Credit != 4 {
376			t.Fatalf("s1 的 r1 应由本人 w1 对应 4 学分课程满足，得到 %+v", st)
377		}
378		if st := rep1.Requirements[1]; st.Req.ID != "r2" || st.Source != "waiver" ||
379			st.WaiverID != "w2" || st.Course.ID != "c2" || st.Course.Credit != 3 {
380			t.Fatalf("s1 的 r2 应由本人 w2 对应 3 学分课程满足，得到 %+v", st)
381		}
382	
383		// s2：同号 r1/w1，但是本人的 3 学分课程与本人依据。
384		rep2 := s.CheckStudent("s2")
385		if rep2.TotalCredits != 3 || len(rep2.Unmet) != 0 {
386			t.Fatalf("s2 应得本人课程的 3 学分，得到学分=%d 未满足=%v", rep2.TotalCredits, rep2.Unmet)
387		}
388		if st := rep2.Requirements[0]; st.Source != "waiver" || st.WaiverID != "w1" ||
389			st.Course.ID != "c2" || st.Course.Credit != 3 {
390			t.Fatalf("s2 的 r1 应由本人 w1 对应本人 3 学分课程满足，得到 %+v", st)
391		}
392	
393		// 同号免修是两条独立记录，归属与依据各归各。
394		w1s1 := s.Waiver("s1", "w1")
395		w1s2 := s.Waiver("s2", "w1")
396		if w1s1 == nil || w1s2 == nil || w1s1 == w1s2 {
397			t.Fatalf("两名学生的同号免修应各自独立，得到 %p %p", w1s1, w1s2)
398		}
399		if w1s1.Basis != "s1-r1 依据" || w1s2.Basis != "s2-r1 依据" ||
400			w1s1.StudentID != "s1" || w1s2.StudentID != "s2" {
401			t.Fatalf("同号免修的依据应各归本人，得到 %+v %+v", w1s1, w1s2)
402		}
403	
404		// 合法记录上的只读核对不得改动文件。
405		_ = s.CheckStudent("s1")
406		_ = s.CheckStudent("s2")
407		_ = s.Waivers("s1")
408		_ = s.Waivers("s2")
409		if s.Dirty() {
410			t.Fatal("只读查询不应把记录标记为已变更")
411		}
412		got, readErr := os.ReadFile(path)
413		if readErr != nil {
414			t.Fatal(readErr)
415		}
416		if string(got) != string(raw) {
417			t.Fatal("只读查询不得改写合法记录文件")
418		}
419	}
