// 首次申请行为不变：按业务规则拒绝（退出码 1），申请与拒绝原因保留在免修
// 历史中并落盘，后续核对可查到该被拒绝申请。
func TestCLIFirstBlankBasisApplicationStillBusinessRejected(t *testing.T) {
	file, _ := writeDiskRecord(t, &diskRecord{
